def backfill_initial_changes(apps, schema_editor):
    """为已有台账补一条「初始」账期/额度记录，保证详情页时间线有起点。"""
    Ledger = apps.get_model("records", "CustomerLedger")
    Log = apps.get_model("records", "CustomerLedgerChangeLog")
    rows = []
    for ledger in Ledger.objects.all().iterator():
        terms = (ledger.payment_terms or "").strip()
        limit = (ledger.credit_limit_text or "").strip()
        if not limit and ledger.credit_limit is not None:
            limit = f"{ledger.credit_limit.normalize():f} 万元"
        for field, value in (("账期", terms), ("额度", limit)):
            if value:
                rows.append(
                    Log(
                        ledger_id=ledger.pk,
                        field=field,
                        old_value="",
                        new_value=value,
                        source="初始",
                        changed_at=ledger.created_at,
                    )
                )
    Log.objects.bulk_create(rows)


